
(async()=>{
  if(window.__V69_GRASS_B) return;
  window.__V69_GRASS_B = true;

  const VERSION = "V69B";
  const MODEL_LABEL = "Realistic Grass Hybrid";
  const TEX_DATA = "data:image/png;base64,";
  const MODEL_GZ_B64 = "";
  const FLIP_V = true;
  const SEED = 6902;

  // V76 — persistent burned grass areas.
  // These areas are applied whenever a grass chunk is created/recreated,
  // so scorched ground remains scorched even after walking away and back.
  const burnedAreas=[];
  const MAX_BURN_AREAS=96;

  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const lerp=(a,b,t)=>a+(b-a)*t;

  function grassBurnFactor(x,z){
    let result=1;

    for(const area of burnedAreas){
      const dx=x-area.x;
      const dz=z-area.z;
      const d=Math.hypot(dx,dz);

      if(d>=area.radius)continue;

      const inner=
        area.radius*
        (
          .66+
          .12*
          area.intensity
        );

      let local;

      if(d<=inner){
        // Almost no standing grass at the core, but leave tiny burnt remnants.
        local=
          .008+
          .020*
          (
            1-
            area.intensity
          );
      }else{
        const edge=
          clamp(
            (d-inner)/
            Math.max(
              .001,
              area.radius-inner
            ),
            0,1
          );

        local=
          lerp(
            .018,
            1,
            edge*edge
          );
      }

      result=Math.min(
        result,
        local
      );
    }

    return result;
  }

  const MOBILE = matchMedia("(pointer:coarse)").matches;
  const WORLD_MIN = -160;
  const WORLD_MAX = 160;
  const CHUNK_SIZE = 18;
  const NEAR_CHUNK_RADIUS = MOBILE ? 1 : 1;
  const FAR_CHUNK_RADIUS = MOBILE ? 2 : 3;
  const FAR_SPACING = MOBILE ? 1.95 : 1.55;
  const FAR_CLUMP_WIDTH = 1.72;
  const FAR_CLUMP_HEIGHT = 0.82;
  const ALPHA_TEST = 0.32;
  const CLEAR_RADIUS = 4.0;
  const LOW_GRASS_RADIUS = 13.0;
  const MEDIUM_GRASS_RADIUS = 20.0;

  const sleep=ms=>new Promise(r=>setTimeout(r,ms));

  async function waitGame(){
    for(let i=0;i<1200;i++){
      const g=window.gameReview;
      if(g?.scene&&g?.player&&g?.groundY&&window.__THREE_MODULE) return g;
      await sleep(20);
    }
    throw new Error("Jogo indisponível para carregar a grama.");
  }

  function hash2(x,z,seed=SEED){
    let n=(Math.imul(x|0,374761393)+Math.imul(z|0,668265263)+seed)|0;
    n=(n^(n>>>13));
    n=Math.imul(n,1274126177);
    n=(n^(n>>>16))>>>0;
    return n/4294967296;
  }

  function grassFactor(x,z){
    const dx=x, dz=z;
    const d=Math.hypot(dx,dz);
    const rand=hash2(Math.floor(x*2.7), Math.floor(z*2.7), SEED+333);

    let base;

    if(d < CLEAR_RADIUS){
      base=0;
    }else if(d < LOW_GRASS_RADIUS){
      base=0.28 + rand*0.24;
    }else if(d < MEDIUM_GRASS_RADIUS){
      base=0.50 + rand*0.25;
    }else{
      base=0.82 + rand*0.35;
    }

    return base*grassBurnFactor(x,z)*(window.gameForestV100?.grassFactor(x,z)??1);
  }

  function makeCardGrassGeometry(THREE){
    const pos=[]; const uv=[]; const normal=[];
    function addCard(angle){
      const ca=Math.cos(angle), sa=Math.sin(angle);
      const half=FAR_CLUMP_WIDTH*.5;
      const x0=-half*ca, z0=-half*sa;
      const x1= half*ca, z1= half*sa;
      const verts=[
        [x0,0,z0,0,0],[x1,0,z1,1,0],[x1,FAR_CLUMP_HEIGHT,z1,1,1],
        [x0,0,z0,0,0],[x1,FAR_CLUMP_HEIGHT,z1,1,1],[x0,FAR_CLUMP_HEIGHT,z0,0,1]
      ];
      const nx=-sa, nz=ca;
      for(const v of verts){ pos.push(v[0],v[1],v[2]); uv.push(v[3],v[4]); normal.push(nx,0,nz); }
    }
    addCard(0); addCard(Math.PI/3); addCard(Math.PI*2/3);
    const geo=new THREE.BufferGeometry();
    geo.setAttribute("position",new THREE.Float32BufferAttribute(pos,3));
    geo.setAttribute("uv",new THREE.Float32BufferAttribute(uv,2));
    geo.setAttribute("normal",new THREE.Float32BufferAttribute(normal,3));
    geo.computeBoundingBox(); geo.computeBoundingSphere();
    return geo;
  }

  async function gunzipB64(s){
    const rawStr=atob(s);
    const raw=new Uint8Array(rawStr.length);
    for(let i=0;i<rawStr.length;i++) raw[i]=rawStr.charCodeAt(i);
    if(typeof DecompressionStream!=='undefined'){
      const ds=new DecompressionStream('gzip');
      return await new Response(new Blob([raw]).stream().pipeThrough(ds)).arrayBuffer();
    }
    if(window.__FFLATE_GUNZIP_SYNC){
      const out=window.__FFLATE_GUNZIP_SYNC(raw);
      return out.buffer.slice(out.byteOffset,out.byteOffset+out.byteLength);
    }
    throw new Error('Sem descompressor gzip disponível.');
  }

  function parseGLB(buffer){
    const dv=new DataView(buffer);
    if(dv.getUint32(0,true)!==0x46546c67) throw new Error('GLB inválido');
    if(dv.getUint32(4,true)!==2) throw new Error('GLB v2 necessário');
    const total=dv.getUint32(8,true);
    let off=12, json=null, bin=null;
    while(off<total){
      const len=dv.getUint32(off,true);
      const type=dv.getUint32(off+4,true);
      off+=8;
      const chunk=buffer.slice(off,off+len);
      off+=len;
      if(type===0x4e4f534a){
        json=JSON.parse(new TextDecoder().decode(new Uint8Array(chunk)).replace(/\u0000+$/,''));
      } else if(type===0x004e4942){
        bin=chunk;
      }
    }
    if(!json||!bin) throw new Error('GLB sem JSON/BIN');
    return {json,bin};
  }

  function compCtor(type){
    switch(type){
      case 5120:return Int8Array;
      case 5121:return Uint8Array;
      case 5122:return Int16Array;
      case 5123:return Uint16Array;
      case 5125:return Uint32Array;
      case 5126:return Float32Array;
      default:throw new Error('componentType '+type+' não suportado');
    }
  }

  function compRead(type){
    switch(type){
      case 5120:return (d,o)=>d.getInt8(o);
      case 5121:return (d,o)=>d.getUint8(o);
      case 5122:return (d,o)=>d.getInt16(o,true);
      case 5123:return (d,o)=>d.getUint16(o,true);
      case 5125:return (d,o)=>d.getUint32(o,true);
      case 5126:return (d,o)=>d.getFloat32(o,true);
      default:throw new Error('componentType '+type+' não suportado');
    }
  }

  function nComp(type){ return ({SCALAR:1,VEC2:2,VEC3:3,VEC4:4,MAT2:4,MAT3:9,MAT4:16})[type]||1; }
  function samplerWrap(THREE,v){ if(v===33071) return THREE.ClampToEdgeWrapping; if(v===33648) return THREE.MirroredRepeatWrapping; return THREE.RepeatWrapping; }
  function samplerFilter(THREE,v,isMag=false){
    const map={9728:THREE.NearestFilter,9729:THREE.LinearFilter,9984:THREE.NearestMipmapNearestFilter,9985:THREE.LinearMipmapNearestFilter,9986:THREE.NearestMipmapLinearFilter,9987:THREE.LinearMipmapLinearFilter};
    return map[v] || (isMag?THREE.LinearFilter:THREE.LinearMipmapLinearFilter);
  }

  async function buildStaticGLB(THREE,buffer){
    const {json:gltf,bin}=parseGLB(buffer);
    const binDV=new DataView(bin);
    const accCache=new Map();
    function accessor(index){
      if(accCache.has(index)) return accCache.get(index);
      const a=gltf.accessors[index];
      const bv=gltf.bufferViews[a.bufferView];
      const Ctor=compCtor(a.componentType);
      const comps=nComp(a.type);
      const bytes=Ctor.BYTES_PER_ELEMENT;
      const stride=bv.byteStride || comps*bytes;
      const start=(bv.byteOffset||0)+(a.byteOffset||0);
      let arr;
      if(stride===comps*bytes && start%bytes===0){
        arr=new Ctor(bin,start,a.count*comps);
      } else {
        arr=new Ctor(a.count*comps);
        const read=compRead(a.componentType);
        for(let i=0;i<a.count;i++){
          const row=start+i*stride;
          for(let c=0;c<comps;c++) arr[i*comps+c]=read(binDV,row+c*bytes);
        }
      }
      const result={array:arr,itemSize:comps,normalized:!!a.normalized,count:a.count};
      accCache.set(index,result);
      return result;
    }

    const textureCache=new Map();
    const blobUrls=[];
    async function textureFor(texIndex,srgb=false){
      const key=texIndex+':'+(srgb?'s':'l');
      if(textureCache.has(key)) return textureCache.get(key);
      const texDef=gltf.textures?.[texIndex];
      if(!texDef) return null;
      const imageDef=gltf.images?.[texDef.source];
      if(!imageDef || imageDef.bufferView==null) return null;
      const bv=gltf.bufferViews[imageDef.bufferView];
      const bytes=new Uint8Array(bin,(bv.byteOffset||0),bv.byteLength);
      const url=URL.createObjectURL(new Blob([bytes],{type:imageDef.mimeType||'application/octet-stream'}));
      blobUrls.push(url);
      const texture=await new THREE.TextureLoader().loadAsync(url);
      texture.flipY=false;
      if(srgb) texture.colorSpace=THREE.SRGBColorSpace;
      const samp=gltf.samplers?.[texDef.sampler];
      if(samp){
        texture.wrapS=samplerWrap(THREE,samp.wrapS);
        texture.wrapT=samplerWrap(THREE,samp.wrapT);
        texture.magFilter=samplerFilter(THREE,samp.magFilter,true);
        texture.minFilter=samplerFilter(THREE,samp.minFilter,false);
      }
      texture.needsUpdate=true;
      textureCache.set(key,texture);
      return texture;
    }

    const materials=[];
    for(const m of gltf.materials||[{}]){
      const p=m.pbrMetallicRoughness||{};
      const f=p.baseColorFactor||[1,1,1,1];
      const mat=new THREE.MeshStandardMaterial({
        color:new THREE.Color(f[0],f[1],f[2]),
        opacity:f[3]??1,
        metalness:p.metallicFactor??0,
        roughness:p.roughnessFactor??1,
        side:m.doubleSided?THREE.DoubleSide:THREE.FrontSide,
        transparent:m.alphaMode==='BLEND'||(f[3]??1)<1,
        alphaTest:m.alphaMode==='MASK'?(m.alphaCutoff??.5):(m.alphaMode==='BLEND'?.18:0)
      });
      if(p.baseColorTexture) mat.map=await textureFor(p.baseColorTexture.index,true);
      if(m.normalTexture){
        mat.normalMap=await textureFor(m.normalTexture.index,false);
        mat.normalScale.set(m.normalTexture.scale??1,m.normalTexture.scale??1);
      }
      if(m.alphaMode==='BLEND'){ mat.depthWrite=true; mat.alphaTest=Math.max(mat.alphaTest,.12); }
      materials.push(mat);
    }
    if(!materials.length) materials.push(new THREE.MeshStandardMaterial({color:0x5f843f,roughness:1,side:THREE.DoubleSide}));

    const nodeLocal=(gltf.nodes||[]).map(n=>{
      const m=new THREE.Matrix4();
      if(n.matrix){ m.fromArray(n.matrix); }
      else {
        const p=new THREE.Vector3().fromArray(n.translation||[0,0,0]);
        const q=new THREE.Quaternion().fromArray(n.rotation||[0,0,0,1]);
        const s=new THREE.Vector3().fromArray(n.scale||[1,1,1]);
        m.compose(p,q,s);
      }
      return m;
    });
    const parents=new Array(gltf.nodes?.length||0).fill(-1);
    (gltf.nodes||[]).forEach((n,i)=>(n.children||[]).forEach(c=>parents[c]=i));
    const worldCache=new Array(nodeLocal.length);
    function nodeWorld(i){
      if(worldCache[i]) return worldCache[i];
      const local=nodeLocal[i]||new THREE.Matrix4();
      worldCache[i]=parents[i]>=0 ? nodeWorld(parents[i]).clone().multiply(local) : local.clone();
      return worldCache[i];
    }

    const primitives=[];
    const overall=new THREE.Box3(); overall.makeEmpty();
    for(let ni=0; ni<(gltf.nodes||[]).length; ni++){
      const n=gltf.nodes[ni];
      if(n.mesh==null) continue;
      const meshDef=gltf.meshes[n.mesh];
      for(const pr of meshDef.primitives||[]){
        if((pr.mode??4)!==4) continue;
        const geo=new THREE.BufferGeometry();
        const attrs={POSITION:'position',NORMAL:'normal',TEXCOORD_0:'uv',COLOR_0:'color'};
        for(const [src,dst] of Object.entries(attrs)){
          const ai=pr.attributes?.[src];
          if(ai==null) continue;
          const a=accessor(ai);
          geo.setAttribute(dst,new THREE.BufferAttribute(a.array,a.itemSize,a.normalized));
        }
        if(pr.indices!=null){
          const a=accessor(pr.indices);
          geo.setIndex(new THREE.BufferAttribute(a.array,1,a.normalized));
        }
        if(!geo.getAttribute('normal')) geo.computeVertexNormals();
        geo.computeBoundingBox(); geo.computeBoundingSphere();
        const wm=nodeWorld(ni).clone();
        const wb=geo.boundingBox.clone().applyMatrix4(wm);
        overall.union(wb);
        const material=materials[pr.material??0]||materials[0];
        material.side=THREE.DoubleSide;
        primitives.push({geometry:geo,material,matrix:wm});
      }
    }
    if(overall.isEmpty()) throw new Error('Nenhum triângulo utilizável no GLB');
    return {primitives,bounds:overall,blobUrls};
  }

  try{
    const game=await waitGame();
    const THREE=window.__THREE_MODULE;

    const farTexture=await new THREE.TextureLoader().loadAsync(TEX_DATA);
    farTexture.colorSpace=THREE.SRGBColorSpace;
    farTexture.flipY=false;
    farTexture.wrapS=THREE.ClampToEdgeWrapping;
    farTexture.wrapT=THREE.ClampToEdgeWrapping;
    if(FLIP_V){ farTexture.wrapT=THREE.RepeatWrapping; farTexture.repeat.y=-1; farTexture.offset.y=1; }
    try{ farTexture.anisotropy=Math.min(4,game.renderer?.capabilities?.getMaxAnisotropy?.()||1); }catch{}
    const farMaterial=new THREE.MeshStandardMaterial({map:farTexture,color:0xf4ffe8,roughness:1,metalness:0,side:THREE.DoubleSide,transparent:false,alphaTest:ALPHA_TEST,depthWrite:true,depthTest:true});
    const farGeometry=makeCardGrassGeometry(THREE);

    const buffer=await gunzipB64(MODEL_GZ_B64);
    const built=await buildStaticGLB(THREE,buffer);
    const size=new THREE.Vector3();
    const center=new THREE.Vector3();
    built.bounds.getSize(size); built.bounds.getCenter(center);
    const normalize=new THREE.Matrix4().makeTranslation(-center.x,-built.bounds.min.y,-center.z);
    const NEAR_BASE_SCALE=0.14;
    const nearStepX=Math.max(3.1, Math.min(8.0, size.x*NEAR_BASE_SCALE*0.82));
    const nearStepZ=Math.max(3.1, Math.min(8.0, size.z*NEAR_BASE_SCALE*0.82));
    const nearJitterX=nearStepX*.28, nearJitterZ=nearStepZ*.28;

    const group=new THREE.Group();
    group.name=`${VERSION}_Grass_${MODEL_LABEL.replace(/\W+/g,"_")}`;
    const nearGroup=new THREE.Group(); nearGroup.name='NearRealisticGrass';
    const farGroup=new THREE.Group(); farGroup.name='FarCardGrass';

    // Burn marks are deliberately separate from the grass instances.
    // That keeps the effect cheap and lets the blackened soil remain visible.
    const scorchGroup=new THREE.Group();
    scorchGroup.name='BurnedGrassScorches_V76';

    const scorchGeometry=
      new THREE.CircleGeometry(
        1,48
      )
      .rotateX(
        -Math.PI/2
      );

    const scorchMaterial=
      new THREE.MeshStandardMaterial({
        color:0x140906,
        roughness:1,
        metalness:0,
        transparent:true,
        opacity:.88,
        depthWrite:false,
        polygonOffset:true,
        polygonOffsetFactor:-2,
        polygonOffsetUnits:-2
      });

    const scorchEdgeMaterial=
      new THREE.MeshBasicMaterial({
        color:0x3a1307,
        transparent:true,
        opacity:.42,
        depthWrite:false,
        blending:THREE.MultiplyBlending,
        side:THREE.DoubleSide,
        polygonOffset:true,
        polygonOffsetFactor:-1,
        polygonOffsetUnits:-1
      });

    group.add(
      scorchGroup,
      nearGroup,
      farGroup
    );

    game.scene.add(group);

    const nearChunks=new Map();
    const farChunks=new Map();
    const tmpM=new THREE.Matrix4();
    const tmpMatrix=new THREE.Matrix4();
    const tmpPos=new THREE.Vector3();
    const tmpQuat=new THREE.Quaternion();
    const tmpScale=new THREE.Vector3();
    const yAxis=new THREE.Vector3(0,1,0);
    const grassNormalTmp=new THREE.Vector3();
    const grassAlignTmp=new THREE.Quaternion();
    const grassYawTmp=new THREE.Quaternion();

    function grassNormalAt(x,z,out=grassNormalTmp){
      const e=.48;
      const hL=game.groundY(x-e,z),hR=game.groundY(x+e,z);
      const hD=game.groundY(x,z-e),hU=game.groundY(x,z+e);
      return out.set(hL-hR,e*2,hD-hU).normalize();
    }

    function mountainGrassWeight(x,z,normal,near=true){
      const edge=window.__V134_BORDER_MASK__?.(x,z)||0;
      if(edge<=0)return 1;
      const route=window.__V134_ROUTE_MASK__?.(x,z)||0;
      const minY=near?.78:.66,fullY=near?.92:.86;
      const slope=clamp((normal.y-minY)/(fullY-minY));
      if(edge<.10)return slope*(1-edge/.10);
      if(route>.42&&edge<.68)return .10*slope;
      return 0;
    }

    function composeGrassMatrix(x,y,z,rot,scaleY,scaleXZ,normal,out){
      grassAlignTmp.setFromUnitVectors(yAxis,normal);
      grassYawTmp.setFromAxisAngle(yAxis,rot);
      tmpQuat.copy(grassAlignTmp).multiply(grassYawTmp);
      tmpPos.set(x,y,z);
      tmpScale.set(scaleXZ,scaleY,scaleXZ);
      return out.compose(tmpPos,tmpQuat,tmpScale);
    }

    function chunkKey(cx,cz){ return `${cx},${cz}`; }

    function createNearChunk(cx,cz){
      const startX=cx*CHUNK_SIZE, startZ=cz*CHUNK_SIZE;
      const cellsX=Math.ceil(CHUNK_SIZE/nearStepX)+2, cellsZ=Math.ceil(CHUNK_SIZE/nearStepZ)+2;
      const placements=[];
      for(let iz=0; iz<cellsZ; iz++){
        for(let ix=0; ix<cellsX; ix++){
          const baseX=startX+(ix+.5)*nearStepX, baseZ=startZ+(iz+.5)*nearStepZ;
          if(baseX>=startX+CHUNK_SIZE||baseZ>=startZ+CHUNK_SIZE) continue;
          const gxCell=Math.floor(baseX/nearStepX), gzCell=Math.floor(baseZ/nearStepZ);
          const jx=(hash2(gxCell,gzCell,SEED+101)-.5)*nearJitterX;
          const jz=(hash2(gxCell+71,gzCell-29,SEED+101)-.5)*nearJitterZ;
          const x=baseX+jx, z=baseZ+jz;
          if(x<WORLD_MIN||x>WORLD_MAX||z<WORLD_MIN||z>WORLD_MAX) continue;

          const normal=grassNormalAt(x,z,grassNormalTmp);
          const slopeWeight=mountainGrassWeight(x,z,normal,true);
          if(slopeWeight<=.035)continue;

          const mountain=Math.hypot(x-48,z+44)<=45;
          const factor=grassFactor(x,z)*slopeWeight;
          if(factor<=0.03) continue;

          const y=game.groundY(x,z)+.012;
          const rot=hash2(gxCell-11,gzCell+37,SEED+101)*Math.PI*2;

          // O modelo próximo de grama é um patch relativamente largo.
          // Na montanha ele fica um pouco menor e alinhado à normal do chão
          // para não virar uma placa horizontal preta atravessando a encosta.
          const footprint=mountain?.70:1;
          const scale=NEAR_BASE_SCALE*(.92+hash2(gxCell+19,gzCell+53,SEED+101)*.20)*factor*footprint;

          const mat=new THREE.Matrix4();
          composeGrassMatrix(x,y,z,rot,scale,scale,normal,mat);
          mat.multiply(normalize);
          placements.push(mat);
        }
      }
      if(!placements.length) return;
      const chunkGroup=new THREE.Group(); chunkGroup.name=`NearGrassChunk_${cx}_${cz}`;
      for(const pr of built.primitives){
        const inst=new THREE.InstancedMesh(pr.geometry,pr.material,placements.length);
        inst.name=chunkGroup.name+'_Instanced'; inst.castShadow=false; inst.receiveShadow=true; inst.frustumCulled=true;
        for(let i=0;i<placements.length;i++){ tmpM.multiplyMatrices(placements[i],pr.matrix); inst.setMatrixAt(i,tmpM); }
        inst.count=placements.length; inst.instanceMatrix.needsUpdate=true; inst.computeBoundingBox?.(); inst.computeBoundingSphere?.(); chunkGroup.add(inst);
      }
      nearGroup.add(chunkGroup); nearChunks.set(chunkKey(cx,cz),{cx,cz,obj:chunkGroup,count:placements.length});
    }

    const farCellsPerChunk=Math.ceil(CHUNK_SIZE/FAR_SPACING)+2; const farCapacity=farCellsPerChunk*farCellsPerChunk;
    function createFarChunk(cx,cz){
      const inst=new THREE.InstancedMesh(farGeometry,farMaterial,farCapacity);
      inst.name=`FarGrassChunk_${cx}_${cz}`; inst.instanceMatrix.setUsage(THREE.DynamicDrawUsage); inst.castShadow=false; inst.receiveShadow=false; inst.frustumCulled=true;
      const startX=cx*CHUNK_SIZE, startZ=cz*CHUNK_SIZE; let count=0;
      for(let iz=0; iz<farCellsPerChunk; iz++){
        for(let ix=0; ix<farCellsPerChunk; ix++){
          const baseX=startX+(ix+.25)*FAR_SPACING, baseZ=startZ+(iz+.25)*FAR_SPACING;
          if(baseX>=startX+CHUNK_SIZE||baseZ>=startZ+CHUNK_SIZE) continue;
          const gxCell=Math.floor(baseX/FAR_SPACING), gzCell=Math.floor(baseZ/FAR_SPACING);
          const jx=(hash2(gxCell,gzCell,SEED)-.5)*FAR_SPACING*.58, jz=(hash2(gxCell+71,gzCell-29,SEED)-.5)*FAR_SPACING*.58;
          const x=baseX+jx, z=baseZ+jz;
          if(x<WORLD_MIN||x>WORLD_MAX||z<WORLD_MIN||z>WORLD_MAX) continue;

          const normal=grassNormalAt(x,z,grassNormalTmp);
          const slopeWeight=mountainGrassWeight(x,z,normal,false);
          if(slopeWeight<=.025)continue;

          const factor=grassFactor(x,z)*slopeWeight;
          if(factor<=0.03) continue;

          const y=game.groundY(x,z)+.018, rot=hash2(gxCell-11,gzCell+37,SEED)*Math.PI*2;
          const mountain=Math.hypot(x-48,z+44)<=45;
          const scale=(.82+hash2(gxCell+19,gzCell+53,SEED)*.38)*factor*(mountain?.90:1);
          const flatten=(.93+hash2(gxCell+41,gzCell-17,SEED)*.15)*(0.92+hash2(gxCell+81,gzCell+7,SEED)*0.16);

          composeGrassMatrix(x,y,z,rot,scale*flatten,scale,normal,tmpMatrix);
          inst.setMatrixAt(count++,tmpMatrix);
        }
      }
      inst.count=count; inst.instanceMatrix.needsUpdate=true; inst.computeBoundingBox?.(); inst.computeBoundingSphere?.(); farGroup.add(inst); farChunks.set(chunkKey(cx,cz),{cx,cz,obj:inst,count});
    }

    function removeChunk(map,key,parent){
      const c=map.get(key);
      if(!c)return;

      parent.remove(c.obj);
      map.delete(key);
    }

    function chunkIntersectsBurn(cx,cz,x,z,radius){
      const minX=cx*CHUNK_SIZE;
      const minZ=cz*CHUNK_SIZE;
      const maxX=minX+CHUNK_SIZE;
      const maxZ=minZ+CHUNK_SIZE;

      const nearestX=
        clamp(
          x,
          minX,
          maxX
        );

      const nearestZ=
        clamp(
          z,
          minZ,
          maxZ
        );

      return (
        Math.hypot(
          x-nearestX,
          z-nearestZ
        )<=radius
      );
    }

    function addScorchVisual(x,z,radius,intensity){
      const y=
        game.groundY(
          x,z
        );

      const disc=
        new THREE.Mesh(
          scorchGeometry,
          scorchMaterial.clone()
        );

      disc.position.set(
        x,
        y+.028,
        z
      );

      disc.scale.set(
        radius*.94,
        radius*.94,
        radius*.94
      );

      disc.rotation.y=
        hash2(
          Math.floor(x*7),
          Math.floor(z*7),
          SEED+919
        )*
        Math.PI*2;

      disc.material.opacity=
        .70+
        .20*
        intensity;

      disc.renderOrder=2;

      scorchGroup.add(
        disc
      );

      // Slight irregular edge: a second, rotated ellipse makes the burn mark
      // read as scorched earth rather than a perfectly clean game-circle.
      const edge=
        new THREE.Mesh(
          scorchGeometry,
          scorchEdgeMaterial.clone()
        );

      edge.position.set(
        x+
        (
          hash2(
            Math.floor(x*11),
            Math.floor(z*13),
            SEED+920
          )-.5
        )*
        radius*.12,

        y+.031,

        z+
        (
          hash2(
            Math.floor(x*17),
            Math.floor(z*5),
            SEED+921
          )-.5
        )*
        radius*.12
      );

      edge.scale.set(
        radius*
        (
          .72+
          .12*
          intensity
        ),

        radius*
        (
          .72+
          .12*
          intensity
        ),

        radius*
        (
          .82+
          .12*
          intensity
        )
      );

      edge.rotation.y=
        disc.rotation.y+
        .83;

      edge.renderOrder=3;

      scorchGroup.add(
        edge
      );
    }

    function rebuildBurnedChunks(x,z,radius){
      const nearToRebuild=[];
      const farToRebuild=[];

      for(const [key,c] of nearChunks){
        if(
          chunkIntersectsBurn(
            c.cx,c.cz,
            x,z,radius
          )
        ){
          nearToRebuild.push(
            [key,c.cx,c.cz]
          );
        }
      }

      for(const [key,c] of farChunks){
        if(
          chunkIntersectsBurn(
            c.cx,c.cz,
            x,z,radius
          )
        ){
          farToRebuild.push(
            [key,c.cx,c.cz]
          );
        }
      }

      for(const [
        key,cx,cz
      ] of nearToRebuild){
        removeChunk(
          nearChunks,
          key,
          nearGroup
        );

        createNearChunk(
          cx,cz
        );
      }

      for(const [
        key,cx,cz
      ] of farToRebuild){
        removeChunk(
          farChunks,
          key,
          farGroup
        );

        createFarChunk(
          cx,cz
        );
      }
    }

    function burnArea(
      x,z,
      radius,
      intensity=1
    ){
      x=Number(x)||0;
      z=Number(z)||0;

      radius=Math.max(
        .6,
        Number(radius)||1
      );

      intensity=
        clamp(
          Number(intensity)||1,
          .15,1
        );

      burnedAreas.push({
        x,z,
        radius,
        intensity
      });

      if(
        burnedAreas.length>
        MAX_BURN_AREAS
      ){
        burnedAreas.splice(
          0,
          burnedAreas.length-
          MAX_BURN_AREAS
        );
      }

      addScorchVisual(
        x,z,
        radius,
        intensity
      );

      rebuildBurnedChunks(
        x,z,
        radius
      );

      return {
        x,z,
        radius,
        intensity,
        total:
          burnedAreas.length
      };
    }

    let lastCX=Infinity,lastCZ=Infinity;

    function refresh(force=false){
      const cx=Math.floor(game.player.x/CHUNK_SIZE), cz=Math.floor(game.player.z/CHUNK_SIZE);
      if(!force&&cx===lastCX&&cz===lastCZ) return; lastCX=cx; lastCZ=cz;
      const wantedNear=new Set(), wantedFar=new Set();
      for(let dz=-FAR_CHUNK_RADIUS; dz<=FAR_CHUNK_RADIUS; dz++){
        for(let dx=-FAR_CHUNK_RADIUS; dx<=FAR_CHUNK_RADIUS; dx++){
          const tx=cx+dx, tz=cz+dz, dist=Math.max(Math.abs(dx),Math.abs(dz)), key=chunkKey(tx,tz);
          if(dist<=NEAR_CHUNK_RADIUS){ wantedNear.add(key); if(!nearChunks.has(key)) createNearChunk(tx,tz); if(farChunks.has(key)) removeChunk(farChunks,key,farGroup); }
          else { wantedFar.add(key); if(!farChunks.has(key)) createFarChunk(tx,tz); if(nearChunks.has(key)) removeChunk(nearChunks,key,nearGroup); }
        }
      }
      for(const key of [...nearChunks.keys()]) if(!wantedNear.has(key)) removeChunk(nearChunks,key,nearGroup);
      for(const key of [...farChunks.keys()]) if(!wantedFar.has(key)) removeChunk(farChunks,key,farGroup);
    }

    refresh(true);
    let lastCheck=0;
    function tick(now){ requestAnimationFrame(tick); if(now-lastCheck<450) return; lastCheck=now; refresh(false); }
    requestAnimationFrame(tick);

    window.gameGrassModel={
      version:"V123B",
      label:MODEL_LABEL,
      group,
      mode:'hybrid-near-realistic-far-cards-burnable',
      nearChunkRadius:NEAR_CHUNK_RADIUS,
      farChunkRadius:FAR_CHUNK_RADIUS,

      get nearChunks(){
        return nearChunks.size;
      },

      get farChunks(){
        return farChunks.size;
      },

      get nearInstances(){
        let n=0;
        for(const c of nearChunks.values())n+=c.count;
        return n;
      },

      get farInstances(){
        let n=0;
        for(const c of farChunks.values())n+=c.count;
        return n;
      },

      get burnedAreas(){
        return burnedAreas.map(
          a=>({...a})
        );
      },

      burnArea,
      refresh:()=>refresh(true)
    };
    const status=document.getElementById('status'); if(status) status.textContent='V123B • grama adaptada ao relevo • encostas sem placas flutuantes';
  }catch(err){
    console.error(`${VERSION} grass`, err);
    const status=document.getElementById('status'); if(status) status.textContent='Falha ao carregar grama híbrida: '+String(err?.message||err);
  }
})();
